from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. 
    Separate groups are balanced and not nested within each other.
    Ignore any spaces in the input string.
    """
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string.")

    result = []
    current_group = []
    level = 0

    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            level += 1
            current_group.append(char)
        elif char == ')':
            level -= 1
            if level < 0:
                raise ValueError("Unbalanced parentheses: found closing brace before opening.")
            current_group.append(char)
            if level == 0:
                result.append("".join(current_group))
                current_group = []
        else:
            raise ValueError(f"Invalid character '{char}' in input.")

    if level != 0:
        raise ValueError("Unbalanced parentheses: missing closing brace.")

    return result
```

